-- Generated from https://github.com/danieltartaro/sticker-swap data/raw/panini-wc-2026-catalog.json
-- Seed ids are deterministic UUID-shaped values so foreign keys stay stable across resets.
SET NAMES utf8mb4;

ON DUPLICATE KEY UPDATE
    collection_id = VALUES(collection_id),
    section_id = VALUES(section_id),
    code = VALUES(code),
    number = VALUES(number),
    name = VALUES(name),
    image_url = VALUES(image_url);
